[CmdletBinding()]
param([string]$IndexPath='ES/Output/ResourceReader/resource-reference-index.json')
$ErrorActionPreference='Stop'; $path=(Resolve-Path -LiteralPath $IndexPath).Path; $obj=Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json; $issues=New-Object Collections.Generic.List[string]
if($obj.indexId -ne 'es-resource-reader.reference-index.v1'){$issues.Add('invalid indexId')}; $refs=@($obj.references); if($obj.guidCount -ne $refs.Count){$issues.Add('guidCount mismatch')}; $edgeSum=0; $previous=''; foreach($ref in $refs){if($ref.guid -notmatch '^[a-f0-9]{32}$'){$issues.Add('invalid guid')}; if($ref.referenceCount -ne @($ref.references).Count){$issues.Add("referenceCount mismatch: $($ref.guid)")}; if($previous -and [string]::CompareOrdinal($previous,$ref.guid) -ge 0){$issues.Add('references are not deterministically sorted')}; $previous=$ref.guid; $edgeSum += @($ref.references).Count; foreach($item in @($ref.references)){if($item.sourceSha256 -notmatch '^[a-f0-9]{64}$'){$issues.Add('invalid source hash')}}}; if($edgeSum -ne [int]$obj.edgeCount){$issues.Add('edgeCount mismatch')}
$out=[ordered]@{validator='Test-ESResourceReaderReferenceIndex';valid=($issues.Count -eq 0);guidCount=$refs.Count;edgeCount=$edgeSum;issueCount=$issues.Count;issues=$issues;runtimeStatus='runtime-not-run'}; $out|ConvertTo-Json -Depth 8; if($issues.Count){exit 1}else{exit 0}
